import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "approving another extraction after the vendor was sent back is refused with vendor_not_in_review",
    { tag: "@LIF-03" },
    async ({ apiAs, factory }) => {
      // Arrange
      const { extractions } = await factory.vendorInReview();
      const reviewer = await apiAs("reviewer");
      await expectStatus(
        await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
          data: { decision: "reject", note: "Wrong counterparty" },
        }),
        200,
      );

      // Act
      const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      const body = await expectStatus(response, 409);
      expect(body.error.code).toBe("vendor_not_in_review");
    },
  );

  test(
    "the refused contract extraction stays pending review",
    { tag: "@LIF-03" },
    async ({ apiAs, factory }) => {
      // Arrange
      const { documents, extractions } = await factory.vendorInReview();
      const reviewer = await apiAs("reviewer");
      await expectStatus(
        await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
          data: { decision: "reject", note: "Wrong counterparty" },
        }),
        200,
      );
      await expectStatus(
        await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
          data: { decision: "approve" },
        }),
        409,
      );

      // Act
      const contract = await factory.extraction(documents.contract.id, "reviewer");

      // Assert
      expect(contract.status).toBe("pending_review");
    },
  );
});
